const D = { energy:.6, scale:1, hue:140, speed:1, density:.5, x:.65, y:.7, wings:.5, chub:.5, horns:.5, pose:'hover', style:'classic', act:'solo', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- helpers ----
const u = Math.min(width, height);
const s = u * 0.0015 * P.scale;
const L = (a, b, t) => a + (b - a) * t;
const fr = i => { const v = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return v - Math.floor(v); };

// ---- seed-keyed structures: ember cracks + belly plate rows ----
if (S.seedUsed !== P.seed || S.densUsed !== P.density) {
  S.seedUsed = P.seed; S.densUsed = P.density;
  S.cracks = [];
  const nc = 3 + Math.round(P.density * 4);
  for (let i = 0; i < nc; i++) {
    const a0 = fr(i + 13) * 6.2832, r0 = .25 + fr(i + 29) * .5;
    const x1 = Math.cos(a0) * 34 * r0, y1 = Math.sin(a0) * 48 * r0;
    const x2 = x1 + (fr(i + 47) - .5) * 30, y2 = y1 + (fr(i + 61) - .5) * 30;
    const x3 = x2 + (fr(i + 83) - .5) * 22, y3 = y2 + (fr(i + 97) - .5) * 22;
    S.cracks.push({ x1, y1, x2, y2, x3, y3, ph: fr(i + 111) * 6.2832 });
  }
  S.ribJit = [fr(201) * .16 - .08, fr(202) * .16 - .08, fr(203) * .16 - .08];
  S.plateRows = 3 + Math.round(fr(204) * 2 + P.density);
}

// ---- clock derivations ----
const bt = K.beat * P.speed;
const ph = ((bt % 1) + 1) % 1;
const pulse = Math.pow(1 - ph, 3);
const kick = Math.min(1, K.pulse * .6 + A.bass * .8);
const step = Math.floor(bt);
const wob = Math.sin(K.t * .21);

// ---- act -> pose + energy envelope ----
let pose = P.pose, em = 1;
if (P.act === 'medley') {
  const seq = ['idle','hover','dance','firebreath','soar','dance','firebreath','hover'];
  pose = seq[((K.section % 8) + 8) % 8];
  em = .55 + K.intensity * .65;
} else if (P.act === 'siege') {
  const sec = ((K.section % 8) + 8) % 8;
  pose = K.intensity > .72 ? 'firebreath' : (sec < 2 ? 'idle' : sec < 4 ? 'soar' : 'hover');
  em = .45 + K.intensity * .7;
}
const E = Math.min(1, Math.max(0, P.energy * em));

// ---- choreography rig ----
let dx = 0, dy = 0, bob = 0, lean = 0, hipX = 0, squash = 0,
    wingL = 0, wingR = 0, fold = 0, legRot = 0, tailAmp = .3, tailRate = 1.6,
    mouth = .08, fireOn = 0, bellyGlow = 0, headRot = 0;

if (pose === 'hover') {
  const raise = ph > .55 ? (ph - .55) / .45 : 0;        // wings lift late in the beat...
  wingL = wingR = (raise * .9 - pulse * 1.1) * E;       // ...and slam down on the pulse
  dy = (-26 - pulse * 10 * E) * s + Math.sin(K.t * .8) * 5 * s;
  legRot = Math.sin(K.t * 2.3) * .18;
  hipX = Math.sin(K.t * .33) * 6 * s;
  tailAmp = .3; tailRate = 1.6;
  headRot = Math.sin(K.t * .5) * .05;
  mouth = .08 + pulse * .06;
} else if (pose === 'idle') {
  fold = 1;
  bob = Math.sin(K.t * 1.1) * 2.2 * s;
  squash = Math.sin(K.t * 1.1) * .02;
  const rf = (((bt / 16) % 1) + 1) % 1;                 // wing ruffle every 4 bars
  wingL = wingR = rf < .1 ? Math.sin(K.t * 26) * .25 * E : -.05;
  tailAmp = .18; tailRate = 1.1;
  headRot = (fr(Math.floor(K.t / 3.1) + 9) - .5) * .4;
  mouth = Math.max(0, Math.sin(K.t * .5)) * .1;
} else if (pose === 'dance') {
  const sway = Math.sin(bt * Math.PI);
  hipX = sway * 10 * s * E; lean = sway * .1 * E;
  bob = (Math.abs(sway) * -4 - pulse * 3) * s * E;
  wingL = ((step % 2 === 0) ? pulse : .12) * -1.2 * E;
  wingR = ((step % 2 === 1) ? pulse : .12) * -1.2 * E;
  headRot = pulse * .35 * E;                            // head bang
  tailAmp = .4; tailRate = 3.2;
  mouth = pulse * .25 * E;
} else if (pose === 'firebreath') {
  const c8 = (((bt / 8) % 1) + 1) % 1;
  const wind = c8 < .18 ? c8 / .18 : (c8 < .25 ? 1 - (c8 - .18) / .07 : 0);   // rear back, then release
  fireOn = (c8 >= .25 && c8 < .8) ? Math.sin((c8 - .25) / .55 * Math.PI) : 0;
  headRot = -wind * .3 + fireOn * .12;
  lean = -wind * .12 + fireOn * .06;
  mouth = wind * .25 + fireOn;
  bellyGlow = wind + fireOn * .5;
  wingL = wingR = -.2 - fireOn * .3 + wind * .4;
  bob = fireOn * Math.sin(K.t * 25) * 1.5 * s * E;
  tailAmp = .25 + fireOn * .3; tailRate = 2;
} else if (pose === 'soar') {
  const a = K.t * .42 * P.speed + P.seed * .1;          // lemniscate flight path
  dx = Math.sin(a) * u * .15;
  dy = -u * .07 + Math.sin(2 * a) * u * .07;
  lean = Math.cos(a) * .3;
  wingL = wingR = Math.sin(bt * Math.PI) * .8 * E - .1;
  legRot = .5;
  tailAmp = .2; tailRate = 1.3; mouth = .05;
}

// ---- palette + morphs ----
const hb = ((P.hue % 360) + 360) % 360;
const hbelly = (hb + 280) % 360;                        // cream belly (preserved from original)
const bodyW = 74 * s * (.82 + P.chub * .42);
const bodyH = 104 * s * (1.06 - P.chub * .16);
const wm = (.6 + P.wings * .9) * (1 - fold * .45);
const hm = .5 + P.horns * 1.0;
const st = P.style;
const lw = Math.max(1, u * .0032);

const cx = P.x * width + wob * u * .012 + dx;
const cy = P.y * height + dy;
// eye positions tracking head rotation about the neck pivot (for accent glows)
const eyc = Math.cos(headRot), eys = Math.sin(headRot);
const eLx = (-10 * eyc - (-28) * eys) * s, eLy = (-10 * eys + (-28) * eyc) * s - 34 * s;
const eRx = (10 * eyc - (-28) * eys) * s, eRy = (10 * eys + (-28) * eyc) * s - 34 * s;

push();

// ground shadow (stays on the ground; fades with altitude)
const hgt = Math.max(0, -(dy + bob)) / (u * .25);
fill(0, 0, 0, 34 * Math.max(.25, 1 - hgt * .7));
ellipse(P.x * width + wob * u * .012, P.y * height + 72 * s, bodyW * 1.5 * (1 - hgt * .35), 13 * s);

translate(cx, cy + bob);

// aura
blendMode(ADD);
noStroke();
const auraR = u * (.15 + .09 * E) * (1 + A.rms * .8) * (1 + Math.sin(K.t * .6) * .06) + kick * u * .02;
fill(hb, 55, 70, 6 + K.intensity * 8 + kick * 5);
ellipse(0, -10 * s, auraR * 2, auraR * 1.7);
blendMode(BLEND);

rotate(lean);
scale(1 + squash, 1 - squash);
translate(hipX, 0);

// ---- style paint system ----
function F(h, sa, b, a) {
  a = a == null ? 100 : a;
  if (st === 'neon') { fill(h, Math.min(sa, 70), Math.min(b * .2, 15), a); stroke(h, 88, 100, Math.min(a, 90)); strokeWeight(lw); }
  else if (st === 'blueprint') { noFill(); stroke(212, 55, 96, Math.min(a, 92)); strokeWeight(Math.max(1, u * .002)); }
  else if (st === 'ember') { noStroke(); fill(h, Math.min(sa, 45), Math.min(b * .28, 20), a); }
  else { noStroke(); fill(h, sa, b, a); }
}

const tailWag = Math.sin(K.t * tailRate + Math.sin(K.t * .45)) * tailAmp;
const blink = ((K.t + P.seed * .17) % 5.3) < .13;

// blueprint construction guides
if (st === 'blueprint') {
  drawingContext.setLineDash([u * .012, u * .009]);
  noFill(); stroke(212, 40, 90, 50); strokeWeight(Math.max(1, u * .0015));
  ellipse(0, 0, bodyW * 1.5, bodyH * 1.3);
  line(-bodyW * .95, 0, bodyW * .95, 0);
  line(0, -bodyH * .75, 0, bodyH * .7);
  drawingContext.setLineDash([]);
}

// tail (K.t wag — aperiodic vs beat)
push(); translate(0, 30 * s); rotate(Math.sin(K.t * (tailRate + .9)) * .3 + tailWag * .4);
F(hb, 70, 55);
beginShape(); vertex(0, 0); vertex(50 * s, 20 * s); vertex(70 * s, 10 * s); vertex(50 * s, 32 * s); vertex(0, 20 * s); endShape(CLOSE);
F(hb, 74, 50);
triangle(66 * s, 4 * s, 84 * s, 12 * s, 66 * s, 26 * s);
pop();

// legs (dangle in the air, planted on the ground)
push(); translate(-16 * s, 52 * s); rotate(legRot); F(hb, 70, 50); ellipse(0, 0, 18 * s, 36 * s); pop();
push(); translate(16 * s, 52 * s); rotate(-legRot); F(hb, 70, 50); ellipse(0, 0, 18 * s, 36 * s); pop();

// wings with seeded membrane ribs
function wing(side, ang) {
  push(); translate(side * 30 * s, -20 * s);
  rotate(side * (.6 + fold * .8) + side * ang * .6);
  const tx1 = side * 56 * s * wm, ty1 = -30 * s;
  const tx2 = side * 40 * s * wm, ty2 = 30 * s;
  F((hb + 15) % 360, 60, 45);
  triangle(0, 0, tx1, ty1, tx2, ty2);
  // ribs
  if (st !== 'ember') {
    stroke(hb, 50, st === 'blueprint' ? 96 : 28, 60); strokeWeight(Math.max(1, u * .0015));
    for (let r = 0; r < 3; r++) {
      const q = .25 + r * .25 + S.ribJit[r];
      line(0, 0, L(tx1, tx2, q), L(ty1, ty2, q));
    }
    noStroke();
  }
  // wing tip sparkle on treble
  if (A.treble > .12 || st === 'neon') {
    blendMode(ADD); noStroke();
    fill((hb + 40) % 360, 40, 100, 25 + A.treble * 55);
    ellipse(tx1, ty1, 6 * s, 6 * s);
    blendMode(BLEND);
  }
  pop();
}
wing(-1, wingL);
wing(1, wingR);

// body + belly
F(hb, 70, 60); ellipse(0, 0, bodyW, bodyH);
F(hbelly, 45, 90); ellipse(0, 12 * s, bodyW * .54, bodyH * .63);
// belly plate rows
if (st !== 'blueprint') {
  stroke(hbelly, 50, 70, 45); strokeWeight(Math.max(1, u * .0015)); noFill();
  for (let r = 0; r < S.plateRows; r++) {
    const yy = (2 + r * 13) * s;
    const w2 = bodyW * .5 * (1 - Math.pow((yy - 12 * s) / (bodyH * .32), 2) * .5);
    arc(0, yy, Math.max(4 * s, w2), 10 * s, .3, Math.PI - .3);
  }
  noStroke();
}
// belly glow (firebreath windup / ember style)
if (bellyGlow > .05 || st === 'ember') {
  blendMode(ADD); noStroke();
  const bg = st === 'ember' ? .35 + kick * .5 + bellyGlow : bellyGlow;
  fill(30, 90, 100, 18 * bg + A.bass * 14);
  ellipse(0, 12 * s, bodyW * .5, bodyH * .5);
  fill(50, 70, 100, 10 * bg);
  ellipse(0, 12 * s, bodyW * .3, bodyH * .3);
  blendMode(BLEND);
}
// arms
F(hb, 70, 55); ellipse(-34 * s, 0, 14 * s, 42 * s); ellipse(34 * s, 0, 14 * s, 42 * s);

// head group (rears back around the neck)
push(); translate(0, -34 * s); rotate(headRot); translate(0, -24 * s);
// horns
F((hb + 220) % 360, 25, 85);
triangle(-14 * s, -22 * s, -7 * s, -22 * s, -16 * s * hm, -42 * s * hm);
triangle(14 * s, -22 * s, 7 * s, -22 * s, 16 * s * hm, -42 * s * hm);
// lower jaw
push(); translate(8 * s, 2 * s); rotate(Math.min(1, mouth) * .55);
F(hb, 72, 52); triangle(8 * s, 2 * s, 40 * s, 10 * s, 10 * s, 12 * s);
pop();
// skull + snout
F(hb, 72, 62); ellipse(0, 0, 60 * s, 50 * s);
F(hb, 72, 55); triangle(18 * s, -8 * s, 52 * s, 0, 20 * s, 8 * s);
// nostril
F(hb, 60, 30); ellipse(44 * s, -2 * s, 3.5 * s, 3.5 * s);
// eyes (front-facing pair, preserved from original)
F(0, 0, 100); ellipse(-10 * s, -4 * s, 12 * s, blink ? 2 * s : 12 * s); ellipse(10 * s, -4 * s, 12 * s, blink ? 2 * s : 12 * s);
if (!blink) {
  const px = lean * 8 * s + (pose === 'soar' ? Math.cos(K.t * .42 * P.speed) * 2.5 * s : wob * 1.5 * s);
  F(0, 0, 8); ellipse(-10 * s + px, -4 * s, 5 * s, 5 * s); ellipse(10 * s + px, -4 * s, 5 * s, 5 * s);
  F(0, 0, 100, 90); ellipse(-11.5 * s, -5.5 * s, 1.8 * s, 1.8 * s); ellipse(8.5 * s, -5.5 * s, 1.8 * s, 1.8 * s);
}
// brows
F(hb, 76, 45); ellipse(-10 * s, -11 * s, 13 * s, 4 * s); ellipse(10 * s, -11 * s, 13 * s, 4 * s);
pop(); // head

// ember cracks — seeded glowing fissures, flicker with the kick
if (st === 'ember') {
  push(); blendMode(ADD); noFill();
  for (const c of S.cracks) {
    const fl = .5 + .5 * Math.sin(K.t * 3.1 + c.ph);
    stroke(24, 95, 100, 26 + 34 * fl * (.5 + kick * .8));
    strokeWeight(Math.max(1, u * .002));
    line(c.x1 * s, c.y1 * s, c.x2 * s, c.y2 * s);
    line(c.x2 * s, c.y2 * s, c.x3 * s, c.y3 * s);
  }
  noStroke();
  fill(20, 90, 100, 30 + kick * 40);
  ellipse(eLx, eLy, 5 * s, 5 * s); ellipse(eRx, eRy, 5 * s, 5 * s);   // coal eyes
  blendMode(BLEND); pop();
}

// neon accents
if (st === 'neon') {
  blendMode(ADD); noStroke();
  fill((hb + 40) % 360, 50, 100, 40 + kick * 40);
  ellipse(eLx, eLy, 6 * s, 6 * s); ellipse(eRx, eRy, 6 * s, 6 * s);
  fill(hb, 30, 100, 20 + A.treble * 45);
  ellipse(0, 0, bodyW * .5, bodyH * .5);
  blendMode(BLEND);
}

// fire breath — cone of additive flame from the snout
if (fireOn > .02 || (pose !== 'firebreath' && kick > .93 && (pose === 'hover' || pose === 'dance') && E > .3)) {
  const f = Math.max(fireOn, (kick - .93) * 8);
  // mouth tip position, tracking head rotation about the neck pivot
  const mx = 48 * s, my = -22 * s;
  const gx = mx * Math.cos(headRot) - my * Math.sin(headRot);
  const gy = mx * Math.sin(headRot) + my * Math.cos(headRot) - 34 * s;
  push(); blendMode(ADD); noStroke();
  const len = (36 + 60 * f * (.6 + .4 * E) + A.bass * 50) * s;
  const nF = 6 + Math.round(P.density * 7);
  for (let i = 0; i < nF; i++) {
    const q = (i + .5) / nF;
    const jit = Math.sin(K.t * 21 + i * 2.4) * (2 + 6 * q) * s;
    const w = (8 + 26 * q) * s * f;
    fill(L(55, 14, q), 95, 100, (52 - 36 * q) * f);
    ellipse(gx + q * len, gy + jit * .6 + q * 5 * s, w * 1.5, w);
  }
  fill(55, 40, 100, 55 * f);
  ellipse(gx + 4 * s, gy, 12 * s * (.5 + f), 9 * s * (.5 + f));
  blendMode(BLEND); pop();
}

blendMode(BLEND);
pop();
